SELECT s5.original_decision AS five_orig, s5.decision AS five_final, COUNT(*) AS n, SUM(p.realized_pnl>0) AS wins, SUM(p.realized_pnl<0) AS losses, ROUND(AVG((p.exit_price-p.entry_price)/p.entry_price*100),4) AS avg_gross_pct FROM paper_position p JOIN trade_signal s5 ON s5.id=(SELECT x.id FROM trade_signal x WHERE x.symbol=p.symbol AND x.interval_code='5m' AND x.generated_at<=p.opened_at ORDER BY x.generated_at DESC LIMIT 1) WHERE p.opened_at>='2026-10-11 00:00:00' AND p.status IN ('CLOSED','STOPPED') GROUP BY s5.original_decision, s5.decision ORDER BY n DESC